import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.util.HashSet;
import java.util.Set;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.apache.poi.ss.usermodel.CellStyle;
import org.apache.poi.ss.usermodel.Cell;
import org.apache.poi.ss.usermodel.Row;
import org.apache.poi.ss.usermodel.Sheet;
import org.apache.poi.ss.usermodel.Font;
import org.apache.poi.ss.usermodel.FillPatternType;
import org.apache.poi.ss.usermodel.IndexedColors;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import org.apache.poi.xwpf.usermodel.XWPFDocument;
import org.apache.poi.xwpf.usermodel.XWPFParagraph;
import org.apache.poi.xwpf.usermodel.XWPFRun;
import org.apache.poi.xwpf.usermodel.XWPFTable;
import org.apache.poi.xwpf.usermodel.XWPFTableRow;
import org.apache.poi.xwpf.usermodel.XWPFTableCell;

public class JA_BuildReportFile extends UserAction<java.lang.String>
{
	/** @deprecated use Report.getMendixObject() instead. */
	@java.lang.Deprecated(forRemoval = true)
	private final IMendixObject __Report;
	private final yourmodule.proxies.GeneratedReport Report;
	private final java.lang.String Format;
	private final java.lang.String Title;
	private final java.lang.String ContentJson;

	public JA_BuildReportFile(
		IContext context,
		IMendixObject _report,
		java.lang.String _format,
		java.lang.String _title,
		java.lang.String _contentJson
	)
	{
		super(context);
		this.__Report = _report;
		this.Report = _report == null ? null : yourmodule.proxies.GeneratedReport.initialize(getContext(), _report);
		this.Format = _format;
		this.Title = _title;
		this.ContentJson = _contentJson;
	}

	@java.lang.Override
	public java.lang.String executeAction() throws Exception
	{
		// BEGIN USER CODE
		String fmt = this.Format == null ? "" : this.Format.trim().toLowerCase();
		String title = (this.Title == null || this.Title.trim().isEmpty()) ? "Report" : this.Title.trim();
		JsonNode root;
		try {
			root = new ObjectMapper().readTree(this.ContentJson == null ? "{}" : this.ContentJson);
		} catch (Exception e) {
			return "The report content was not valid. Send it again as a list of sections with headings, headers and rows.";
		}
		JsonNode sections = root.path("sections");
		if (!sections.isArray() || sections.size() == 0) {
			return "The report has no sections. Add at least one section with headers and rows.";
		}
		String subtitle = root.path("subtitle").asText("");
		String safeName = title.replaceAll("[^A-Za-z0-9._-]+", "_");
		if (safeName.length() > 60) safeName = safeName.substring(0, 60);
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		String ext;
		
		if (fmt.equals("excel") || fmt.equals("xlsx")) {
			ext = ".xlsx";
			try (XSSFWorkbook wb = new XSSFWorkbook()) {
				CellStyle head = wb.createCellStyle();
				Font hf = wb.createFont();
				hf.setBold(true);
				head.setFont(hf);
				head.setFillForegroundColor(IndexedColors.GREY_25_PERCENT.getIndex());
				head.setFillPattern(FillPatternType.SOLID_FOREGROUND);
				CellStyle bold = wb.createCellStyle();
				Font bf = wb.createFont();
				bf.setBold(true);
				bf.setFontHeightInPoints((short) 14);
				bold.setFont(bf);
				Set<String> used = new HashSet<String>();
				int idx = 0;
				for (JsonNode sec : sections) {
					idx++;
					String sn = sec.path("heading").asText("Section " + idx).replaceAll("[\\\\/?*\\[\\]:]", " ").trim();
					if (sn.isEmpty()) sn = "Section " + idx;
					if (sn.length() > 31) sn = sn.substring(0, 31);
					String base = sn;
					int n = 2;
					while (used.contains(sn.toLowerCase())) {
						String suf = " (" + n++ + ")";
						sn = base.substring(0, Math.min(base.length(), 31 - suf.length())) + suf;
					}
					used.add(sn.toLowerCase());
					Sheet sh = wb.createSheet(sn);
					int r = 0;
					Row tr = sh.createRow(r++);
					Cell tc = tr.createCell(0);
					tc.setCellValue(title);
					tc.setCellStyle(bold);
					if (!subtitle.isEmpty()) sh.createRow(r++).createCell(0).setCellValue(subtitle);
					String para = sec.path("text").asText("");
					if (!para.isEmpty()) sh.createRow(r++).createCell(0).setCellValue(para);
					r++;
					JsonNode hs = sec.path("headers");
					int cols = 0;
					if (hs.isArray() && hs.size() > 0) {
						Row hr = sh.createRow(r++);
						int c = 0;
						for (JsonNode h : hs) {
							Cell hc = hr.createCell(c++);
							hc.setCellValue(h.asText(""));
							hc.setCellStyle(head);
						}
						cols = c;
					}
					for (JsonNode rowNode : sec.path("rows")) {
						Row rr = sh.createRow(r++);
						int c = 0;
						for (JsonNode v : rowNode) {
							Cell cell = rr.createCell(c++);
							String s = v.asText("");
							// numbers stay numbers so they can be summed in Excel
							if (v.isNumber()) cell.setCellValue(v.asDouble());
							else cell.setCellValue(s);
						}
						if (c > cols) cols = c;
					}
					for (int c = 0; c < cols; c++) {
						sh.autoSizeColumn(c);
						if (sh.getColumnWidth(c) > 60 * 256) sh.setColumnWidth(c, 60 * 256);
					}
				}
				wb.write(out);
			} catch (Exception e) {
				return "The Excel file could not be built: " + e.getMessage();
			}
		} else if (fmt.equals("word") || fmt.equals("docx")) {
			ext = ".docx";
			try (XWPFDocument doc = new XWPFDocument()) {
				XWPFParagraph tp = doc.createParagraph();
				XWPFRun tr = tp.createRun();
				tr.setBold(true);
				tr.setFontSize(18);
				tr.setText(title);
				if (!subtitle.isEmpty()) {
					XWPFRun sr = doc.createParagraph().createRun();
					sr.setItalic(true);
					sr.setText(subtitle);
				}
				for (JsonNode sec : sections) {
					String hd = sec.path("heading").asText("");
					if (!hd.isEmpty()) {
						XWPFRun hr = doc.createParagraph().createRun();
						hr.setBold(true);
						hr.setFontSize(14);
						hr.setText(hd);
					}
					String para = sec.path("text").asText("");
					if (!para.isEmpty()) doc.createParagraph().createRun().setText(para);
					JsonNode hs = sec.path("headers");
					JsonNode rows = sec.path("rows");
					int cols = hs.isArray() ? hs.size() : 0;
					for (JsonNode rowNode : rows) if (rowNode.size() > cols) cols = rowNode.size();
					if (cols > 0) {
						XWPFTable t = doc.createTable();
						boolean first = true;
						if (hs.isArray() && hs.size() > 0) {
							XWPFTableRow hrw = t.getRow(0);
							for (int c = 0; c < cols; c++) {
								XWPFTableCell cell = c == 0 ? hrw.getCell(0) : hrw.addNewTableCell();
								XWPFRun cr = cell.getParagraphs().get(0).createRun();
								cr.setBold(true);
								cr.setText(c < hs.size() ? hs.get(c).asText("") : "");
							}
							first = false;
						}
						for (JsonNode rowNode : rows) {
							XWPFTableRow rw = first ? t.getRow(0) : t.createRow();
							first = false;
							for (int c = 0; c < cols; c++) {
								XWPFTableCell cell = rw.getCell(c) != null ? rw.getCell(c) : rw.addNewTableCell();
								cell.setText(c < rowNode.size() ? rowNode.get(c).asText("") : "");
							}
						}
					}
					doc.createParagraph();
				}
				doc.write(out);
			} catch (Exception e) {
				return "The Word file could not be built: " + e.getMessage();
			}
		} else if (fmt.equals("pdf")) {
			ext = ".pdf";
			com.lowagie.text.Document pdfDoc = new com.lowagie.text.Document(com.lowagie.text.PageSize.A4.rotate(), 28, 28, 28, 28);
			try {
				com.lowagie.text.pdf.PdfWriter.getInstance(pdfDoc, out);
				pdfDoc.open();
				com.lowagie.text.Font titleFont = com.lowagie.text.FontFactory.getFont(com.lowagie.text.FontFactory.HELVETICA_BOLD, 18);
				com.lowagie.text.Font headFont = com.lowagie.text.FontFactory.getFont(com.lowagie.text.FontFactory.HELVETICA_BOLD, 13);
				com.lowagie.text.Font cellFont = com.lowagie.text.FontFactory.getFont(com.lowagie.text.FontFactory.HELVETICA, 9);
				com.lowagie.text.Font cellBold = com.lowagie.text.FontFactory.getFont(com.lowagie.text.FontFactory.HELVETICA_BOLD, 9);
				com.lowagie.text.Font noteFont = com.lowagie.text.FontFactory.getFont(com.lowagie.text.FontFactory.HELVETICA_OBLIQUE, 10);
				pdfDoc.add(new com.lowagie.text.Paragraph(title, titleFont));
				if (!subtitle.isEmpty()) pdfDoc.add(new com.lowagie.text.Paragraph(subtitle, noteFont));
				for (JsonNode sec : sections) {
					String hd = sec.path("heading").asText("");
					com.lowagie.text.Paragraph hp = new com.lowagie.text.Paragraph(hd, headFont);
					hp.setSpacingBefore(14);
					hp.setSpacingAfter(4);
					if (!hd.isEmpty()) pdfDoc.add(hp);
					String para = sec.path("text").asText("");
					if (!para.isEmpty()) pdfDoc.add(new com.lowagie.text.Paragraph(para, cellFont));
					JsonNode hs = sec.path("headers");
					JsonNode rows = sec.path("rows");
					int cols = hs.isArray() ? hs.size() : 0;
					for (JsonNode rowNode : rows) if (rowNode.size() > cols) cols = rowNode.size();
					if (cols > 0) {
						com.lowagie.text.pdf.PdfPTable t = new com.lowagie.text.pdf.PdfPTable(cols);
						t.setWidthPercentage(100);
						t.setSpacingBefore(4);
						if (hs.isArray() && hs.size() > 0) {
							for (int c = 0; c < cols; c++) {
								com.lowagie.text.pdf.PdfPCell hc = new com.lowagie.text.pdf.PdfPCell(new com.lowagie.text.Phrase(c < hs.size() ? hs.get(c).asText("") : "", cellBold));
								hc.setBackgroundColor(java.awt.Color.LIGHT_GRAY);
								t.addCell(hc);
							}
							t.setHeaderRows(1);
						}
						for (JsonNode rowNode : rows) {
							for (int c = 0; c < cols; c++) {
								t.addCell(new com.lowagie.text.Phrase(c < rowNode.size() ? rowNode.get(c).asText("") : "", cellFont));
							}
						}
						pdfDoc.add(t);
					}
				}
				pdfDoc.close();
			} catch (Exception e) {
				return "The PDF file could not be built: " + e.getMessage();
			}
		} else {
			return "The format '" + this.Format + "' is not available. Use excel, word or pdf.";
		}
		
		byte[] bytes = out.toByteArray();
		com.mendix.systemwideinterfaces.core.IMendixObject target = this.Report.getMendixObject();
		target.setValue(getContext(), "ReportTitle", title);
		target.setValue(getContext(), "ReportFormat", fmt);
		Core.storeFileDocumentContent(getContext(), target, safeName + ext, new ByteArrayInputStream(bytes));
		return "";
		// END USER CODE
	}

	/**
	 * Returns a string representation of this action
	 * @return a string representation of this action
	 */
	@java.lang.Override
	public java.lang.String toString()
	{
		return "JA_BuildReportFile";
	}

	// BEGIN EXTRA CODE
	// END EXTRA CODE
}
